 function requestForm(key,decision){const r=entries().find(r=>r.key===key);if(!r)return;const a=r.accion;show(`<form data-g-form="request" data-key="${E(key)}" data-version="${E(a.actualizadoEn||a.creadoEn||'')}"><h3>${{aceptar:'Aceptar acción',rechazar:'Rechazar acción',reprogramar:'Reprogramar acción'}[decision]}</h3><p>${E(a.titulo)} · ${date(a.fecha)}</p><input type="hidden" name="decision" value="${E(decision)}">${decision==='reprogramar'?`<label>Nueva fecha<input name="fecha" type="date" min="${today()}" required></label>`:''}${decision==='reprogramar'?`<label>Causa<select name="causa" required><option value="">Seleccionar causa…</option>${G.REPLAN_CAUSES.map(([id,label])=>`<option value="${id}">${E(label)}</option>`).join('')}</select></label><label>Atribución<select name="responsabilidad">${G.RESPONSIBILITIES.map(([id,label])=>`<option value="${id}" ${id==='pendiente'?'selected':''}>${E(label)}</option>`).join('')}</select></label>`:''}${decision!=='aceptar'?'<label>Motivo para quien cargó la acción<textarea name="motivo" required maxlength="2000" rows="3"></textarea></label>':''}<button type="submit" class="btn btn-primary">Guardar respuesta</button></form>`);}
 async function saveRequest(f){if(S.saving)return;const r=entries().find(r=>r.key===f.dataset.key);if(!r)return;S.saving=true;const b=f.querySelector('button[type=submit]');b.disabled=true;try{const result=await api({mode:'request-response',id:r.accion.id,obraId:r.draft?'':r.obra.id,version:f.dataset.version,response:Object.fromEntries(new FormData(f))});if(r.draft){const i=S.drafts.findIndex(a=>a.id===r.accion.id);if(i>=0)S.drafts[i]=result.action;scheduleSheet({drafts:[r.accion.id]});}else{r.obra.colocacionesGestion.acciones[r.accion.id]=result.action;changed(r.obra.id);}modal?.remove();modal=null;redraw();window.showToast?.('Respuesta de Ariel guardada ✓');}catch(e){document.getElementById('g129-error').textContent=e.message;b.disabled=false;}finally{S.saving=false;}}
 function compactRow(r){const a=r.accion,description=r.obra.desc||r.obra.descripcion||a.referencia||r.cliente||'Sin descripción';return `<div class="g147-list-row ${!r.draft?'g147-with-analysis':''}"><div class="g147-work-summary"><b>${E(r.obra.ot?'OT '+r.obra.ot:'Sin OT')} · ${E(r.cliente||r.obra.cliente||'Sin cliente')} · ${E(description)}</b><div class="g147-task">${E(a.titulo||'Sin acción cargada')}</div>${requestBadge(a)}${requestControls(r)}${reviewBadge(a)}${!r.draft&&write()&&!r.obra.colocacionesGestion?.cierre?.cerrada?button('✓ Ya se realizó',`data-g-performed="${E(r.obra.id)}"`):''}${r.newWork?'<span class="g149-new">Obra nueva · revisar y planificar</span>':''}</div>${!r.draft?`<div class="g147-analysis"><div data-ap-ot="${E(r.obra.ot)}" data-ap-id="${E(r.obra.id)}" data-ap-puesto="colocaciones"></div></div>`:''}<button type="button" class="btn-icon" data-g-detail="${E(r.key)}" title="Abrir detalle de la tarea" aria-label="Abrir detalle de ${E(r.obra.ot||'Sin OT')}: ${E(a.titulo)}"><i class="ti ti-edit" aria-hidden="true"></i></button></div>`}
