  const planned=C().isoDate(a.fecha),real=C().isoDate(a.revisionCierre?.estado==='Aprobado'?a.revisionCierre.fechaValidada:a.fechaReal),days=(from,to)=>Math.round((Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000);
