 function planningCalendar(p,byDay){const first=G.week(p.from).start,last=G.shift(G.week(p.to).start,6),count=Math.round((Date.parse(last)-Date.parse(first))/86400000)+1;return `<div class="g-date-scroll"><div class="g-date-grid" aria-label="Calendario de colocaciones">${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'].map(d=>`<div class="g-date-heading">${d}</div>`).join('')}${Array.from({length:count},(_,i)=>{const d=G.shift(first,i),outside=d<p.from||d>p.to;return `<div class="${outside?'g-date-padding':d===today()?'today':''}"><time datetime="${d}">${date(d)}</time>${outside?'':(byDay.get(d)||[]).map(r=>`<button type="button" class="g-date-event" data-g-detail="${E(r.key)}"><b>${r.obra.ot?'OT '+E(r.obra.ot):'Sin OT'} · ${E(r.cliente)}</b><small>${E(r.accion.titulo)}</small><small>${E(r.obra.desc||'')}</small><small>${r.accion.todoDia===false?E(r.accion.hora||'')+' · ':''}${E(r.accion.responsable||'Sin asignar')}</small></button>`).join('')}</div>`}).join('')}</div></div>`}
 function datesBody(start){const p=planningWindow(start),pending=entries().filter(r=>G.open(r.accion)&&G.needsAcceptance(r.accion)),rows=entries().filter(r=>G.scheduled(r.accion)&&matches(r,true)),undated=rows.filter(r=>!r.accion.fecha),byDay=new Map();for(const r of rows){const d=r.accion.fecha;if(d&&d>=p.from&&d<=p.to){if(!byDay.has(d))byDay.set(d,[]);byDay.get(d).push(r)}}for(const list of byDay.values())list.sort((a,b)=>(a.accion.hora||'99:99').localeCompare(b.accion.hora||'99:99')||a.key.localeCompare(b.key));const count=[...byDay.values()].reduce((n,list)=>n+list.length,0);return planningToolbar(p)+(pending.length?`<p class="c128-note">${pending.length} pedidos esperan aceptación de Ariel y todavía no están en el calendario. ${button('Ver solicitudes','data-view="solicitudes"')}</p>`:'')+(p.error?`<p role="alert">${E(p.error)}</p>`:`<p class="c128-muted">${count} acciones abiertas en el período.</p>`+(S.dateMode==='calendar'?planningCalendar(p,byDay):Array.from({length:p.days},(_,i)=>{const d=G.shift(p.from,i);return dateGroup(d,byDay.get(d)||[])}).join('')))+(undated.length?`<details style="margin-top:14px"><summary>Acciones abiertas sin fecha (${undated.length})</summary>${dateGroup('',undated)}</details>`:'')+`<p class="c128-muted">Las acciones terminadas, reprogramadas y canceladas se conservan en <button type="button" class="btn btn-ghost btn-sm" data-view="historico">Histórico</button>.</p>`}
