 function printOrder(id){const o=(DB().obras||[]).find(o=>o.id===id&&!o.archivado&&o.revisionVigente!==false&&o.revisionOperativa!==false);if(!o||!window.canViewPage?.('colocaciones'))return window.showToast?.('No se encontró una OT disponible para imprimir.');const l=C().logistics(o,DB()),contacts=C().contacts(o,DB()),items=[o.itemsTecnicos,o.itemsCotizados,o.infoPresupuesto?.items].find(a=>Array.isArray(a)&&a.length)||[],modes={colocacion:'Con colocación',retiro_fabrica:'Retiro en fábrica',envio:'Envío a domicilio',a_definir:'A definir'},delivery=o.entregaLogistica||{},rows=items.map(it=>({articulo:it.articulo||it.descripcion||it.desc||'',cantidad:it.cantidad??it.cant??it.unidades??1,unidad:it.unidad||'UNID',observaciones:it.observaciones||it.detalle||''}));printHtml('Orden de trabajo · OT '+o.ot,`<h2>${E(o.cliente)}</h2><p>${E(o.desc||o.descripcion||'')}</p><p>Estado: ${E(o.estado||'—')} · Revisión: ${E(o.revisionCotizacion||'—')}</p><h3>Detalle del trabajo</h3>${rows.length?`<table><thead><tr><th>Descripción / alcance</th><th>Cantidad</th><th>Unidad</th></tr></thead><tbody>${rows.map(it=>`<tr><td>${E(it.articulo)}${it.observaciones?`<small>${E(it.observaciones)}</small>`:''}</td><td>${E(it.cantidad)}</td><td>${E(it.unidad)}</td></tr>`).join('')}</tbody></table>`:'<p>Detalle: '+E(o.desc||o.descripcion||'Sin detalle cargado')+'</p>'}<h3>Entrega / colocación</h3><p>${E(modes[delivery.tipo]||delivery.tipo||'A definir')}</p><p>Domicilio: ${E(l.direccion||'Sin domicilio cargado')}</p><p>Fecha prevista: ${E(o.sectores?.colocaciones?.compromiso||o.fcol_c||delivery.fecha||'Sin fecha')}</p>${l.indicaciones?`<p>Indicaciones: ${E(l.indicaciones)}</p>`:''}<h3>Contactos</h3>${contacts.map(c=>`<p>${E(c.nombre)} · ${E(c.cargo||'')} · ${E(c.telefono||'')} · ${E(c.email||'')}</p>`).join('')||'<p>Sin contactos cargados.</p>'}<section><p>Recibido por: __________________________</p><p>Fecha: __________________ Firma: __________________</p></section>`,'portrait');}
 function printWork(id){const o=(DB().obras||[]).find(o=>o.id===id);if(!o)return;const l=C().logistics(o,DB()),rep=G.report({...o,colocacionesGestion:{...o.colocacionesGestion,direccion:l.direccion}},C().contacts(o,DB()),C().actions(o,DB()).filter(a=>a.virtual));const rows=entries().filter(r=>r.obra.id===id);printHtml('Colocaciones · OT '+o.ot,`<h2>${E(o.cliente)} · ${E(o.desc)}</h2><p>Domicilio: ${E(rep.direccion)} · Zona: ${E(rep.zona)}</p><h3>Contactos</h3>${rep.contactos.map(c=>`<p>${E(c.nombre)} · ${E(c.cargo)} · ${E(c.telefono)} · ${E(c.email)}</p>`).join('')}${printTable(rows)}<h3>Preparación</h3>${rep.preparacion.map(c=>`<section><b>${E(c.paso)} · ${E(c.estado)}</b><p>${E(c.detalle)} · ${E(c.url)}</p></section>`).join('')}<h3>Ayudamemorias</h3>${rep.notas.map(n=>`<section>${E(n.tipo)} · ${E(n.texto)}</section>`).join('')}`)}
